/* Catppuccin Mocha space night (dark only). Light mode is untouched. */
html.dark {
  background: radial-gradient(120% 90% at 50% 0%, #161834 0%, #0d0e1c 55%, #08091a 100%) #0b0c1a !important;
}
/* Let the sky show through the app's opaque base layers. */
html.dark body,
.dark [data-slot="sidebar-inset"],
.dark [data-slot="sidebar-inset"] > div:has(> [data-chat-column]),
.dark [data-workspace-area="conversation"] {
  background: transparent !important;
}
.dark [data-chat-header] {
  background: linear-gradient(to bottom, rgb(11 12 26 / 0.7), rgb(11 12 26 / 0)) !important;
}
.dark [data-slot="sidebar-inner"] {
  background: rgb(10 11 22 / 0.62) !important;
  border-right: 1px solid rgb(180 190 254 / 0.08);
}
.dark [data-slot="composer-host"] { box-shadow: 0 0 0 1px rgb(203 166 247 / 0.14), 0 8px 30px rgb(0 0 0 / 0.35); }
.dark [data-user-message-bubble] { box-shadow: 0 0 0 1px rgb(137 180 250 / 0.12); }
.dark .chat-markdown { text-shadow: 0 0 6px rgb(11 12 26 / 0.9); }

/* Sky layers: fixed, behind everything; animate only transform/opacity so the GPU composites instead of repainting. */
html.dark::before, html.dark body::before, html.dark body::after, html.dark #root::before {
  content: ""; position: fixed; z-index: -1; pointer-events: none;
}
/* Nebula glow: mauve + blue, slow breathing. */
html.dark::before {
  inset: -10%;
  background:
    radial-gradient(38% 30% at 22% 28%, rgb(203 166 247 / 0.16), transparent 70%),
    radial-gradient(34% 28% at 78% 64%, rgb(137 180 250 / 0.14), transparent 70%),
    radial-gradient(26% 22% at 60% 12%, rgb(245 194 231 / 0.07), transparent 70%);
  animation: t3sky-nebula 48s ease-in-out infinite alternate;
  will-change: transform, opacity;
}
