/* The app's .no-transitions rule zeroes every ::before/::after animation; keep the sky moving anyway. */
html.dark::before { animation-duration: 48s !important; }
html.dark body::before { animation-duration: 256s !important; }
html.dark body::after { animation-duration: 336s, 7s !important; }
html.dark #root::before { animation-duration: 416s, 9s !important; }
@keyframes t3sky-drift-x  { to { transform: translate3d(-640px, 0, 0); } }
@keyframes t3sky-drift-x2 { to { transform: translate3d(-720px, 0, 0); } }
@keyframes t3sky-drift-y  { to { transform: translate3d(0, -560px, 0); } }
@keyframes t3sky-twinkle  { from { opacity: 0.25; } to { opacity: 1; } }
@keyframes t3sky-nebula   { from { opacity: 0.7; transform: scale(1); } to { opacity: 1; transform: scale(1.06); } }

/* Reduced motion: static stars, no drift or twinkle. */
@media (prefers-reduced-motion: reduce) {
  html.dark::before, html.dark body::before, html.dark body::after, html.dark #root::before {
    animation: none !important; opacity: 0.85;
  }
}
